  $locked=[];$freshTotal=0;$lock=$db->prepare('SELECT id,name,price,stock FROM san_pham WHERE id=? AND active=1 FOR UPDATE');foreach($cart as $id=>$qty){$id=(int)$id;$qty=(int)$qty;$lock->bind_param('i',$id);$lock->execute();$p=$lock->get_result()->fetch_assoc();if(!$p||(int)$p['stock']<$qty)throw new DomainException('Một món vừa hết hoặc không đủ số lượng trong kho. Hãy cập nhật giỏ hàng.');$p['qty']=$qty;$locked[]=$p;$freshTotal+=(float)$p['price']*$qty;}$lock->close();
  $q=$db->prepare("INSERT INTO don_hang(user_id,customer_name,phone,address,note,total,status) VALUES(?,?,?,?,?,?,'pending')");$uid=(int)user()['id'];$q->bind_param('issssd',$uid,$name,$phone,$address,$note,$freshTotal);$q->execute();$oid=$db->insert_id;$line=$db->prepare('INSERT INTO chi_tiet_don_hang(order_id,product_id,product_name,price,quantity) VALUES(?,?,?,?,?)');$decrement=$db->prepare('UPDATE san_pham SET stock=stock-? WHERE id=? AND stock>=?');foreach($locked as $p){$line->bind_param('iisdi',$oid,$p['id'],$p['name'],$p['price'],$p['qty']);$line->execute();$decrement->bind_param('iii',$p['qty'],$p['id'],$p['qty']);$decrement->execute();if($decrement->affected_rows!==1)throw new DomainException('Tồn kho đã thay đổi. Vui lòng thử đặt hàng lại.');}$db->commit();unset($_SESSION['cart']);flash("Đặt hàng thành công! Mã đơn #$oid");go('index.php?page=taikhoan');
