function auth_form($mode,$error) { ?><div class="auth-wrap"><form method="post" class="form-card auth"><span class="eyebrow">STARBUCKS CAFE</span><h1><?=$mode==='login'?'Chào bạn trở lại.':'Tạo tài khoản mới.'?></h1><p><?=$mode==='login'?'Đăng nhập để theo dõi đơn hàng của bạn.':'Đăng ký để đặt món và xem lịch sử đơn hàng.'?></p><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><?php if($mode==='register'):?><label>Họ và tên<input required name="name" value="<?=e($_POST['name']??'')?>"></label><label>Số điện thoại<input required name="phone" value="<?=e($_POST['phone']??'')?>"></label><?php endif;?><label>Email<input required type="email" name="email" value="<?=e($_POST['email']??'')?>"></label><label>Mật khẩu<input required type="password" name="password" minlength="8"></label><button class="btn btn-dark full"><?=$mode==='login'?'Đăng nhập':'Đăng ký tài khoản'?> ↗</button><p class="auth-switch"><?=$mode==='login'?'Chưa có tài khoản?':'Đã có tài khoản?'?> <a href="index.php?page=<?=$mode==='login'?'dangky':'dangnhap'?>"><?=$mode==='login'?'Đăng ký':'Đăng nhập'?></a></p></form></div><?php }
if ($page === 'logout') { unset($_SESSION['user']);session_regenerate_id(true);flash('Bạn đã đăng xuất. Hẹn gặp lại!');go('index.php'); }
if ($page === 'account') {require_login();$uid=user()['id'];$q=$db->prepare('SELECT * FROM don_hang WHERE user_id=? ORDER BY created_at DESC');$q->bind_param('i',$uid);$q->execute();$orders=$q->get_result();render_header('Tài khoản');?><section class="page-intro"><span class="eyebrow">TÀI KHOẢN CỦA BẠN</span><h1>Xin chào, <?=e(user()['name'])?>.</h1><p><?=e(user()['email'])?> · <a href="index.php?page=dangxuat">Đăng xuất</a></p></section><section class="section orders"><h2>Lịch sử đơn hàng</h2><?php if(!$orders->num_rows):?><div class="empty"><p>Bạn chưa có đơn hàng nào.</p><a class="btn btn-dark" href="index.php?page=cuahang">Gọi món đầu tiên ↗</a></div><?php else:while($o=$orders->fetch_assoc()):?><article class="order-card"><div><b>Đơn #<?=$o['id']?></b><span><?=date('d/m/Y H:i',strtotime($o['created_at']))?></span></div><div><span class="status"><?=e(order_status($o['status']))?></span><b><?=money($o['total'])?></b></div><p><?=e($o['customer_name'])?> · <?=e($o['address'])?></p></article><?php endwhile;endif;?></section><?php render_footer();exit; }
